from datetime import datetime, timezone
import sqlite3

import importers
import uniclubs_database
import uniclubs_export


EVENT_UPDATE_FIELDS = (
    'club_id', 'title', 'start_utc', 'end_utc', 'location', 'event_type', 'source_url',
    'publication_status', 'availability_state', 'requires_membership', 'last_seen_utc',
    'source_missing',
)
INSERT_EVENT_SQL = '''INSERT INTO events (id, external_id, club_id, title, start_utc,
    end_utc, location, event_type, source_url, publication_status, availability_state,
    requires_membership, first_seen_utc, last_seen_utc, source_missing)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'''
UPDATE_EVENT_SQL = '''UPDATE events SET club_id=?, title=?, start_utc=?, end_utc=?,
    location=?, event_type=?, source_url=?, publication_status=?, availability_state=?,
    requires_membership=?, last_seen_utc=?, source_missing=? WHERE id=?'''


class OutdatedSnapshot(ValueError):
    """Indicate a valid feed whose source observation predates the saved catalog."""


def get_current_source_success(connection):
    """Return the last successful source observation, excluding failed local checks."""
    row = connection.execute('''SELECT MAX(imported_at_utc) FROM import_log
        WHERE status='success' ''').fetchone()
    return row[0]


def _current_catalog(connection):
    """Read only public fields, retaining missing and historical rows for identity checks."""
    clubs = connection.execute('''SELECT id, external_id, name, source_url
        FROM clubs ORDER BY id''').fetchall()
    events = connection.execute('''SELECT id, external_id, club_id, title, start_utc,
        end_utc, location, event_type, source_url, publication_status, availability_state,
        requires_membership, first_seen_utc, last_seen_utc, source_missing
        FROM events ORDER BY id''').fetchall()
    return ({row['id']: dict(row) for row in clubs},
            {row['id']: dict(row) for row in events})


def _check_identities(incoming, existing, label):
    """Reject identity rebinding that could redirect private references to another event."""
    by_source = {row['external_id']: row for row in existing.values()}
    for record in incoming:
        local = existing.get(record['id'])
        source = by_source.get(record['external_id'])
        if ((local is not None and local['external_id'] != record['external_id'])
                or (source is not None and source['id'] != record['id'])):
            raise ValueError(f'The public feed changed an existing {label} identity.')


def _check_snapshot(connection, document, clubs, events):
    """Require monotonic source time, stable IDs and unchanged first observations."""
    observed = document['_meta']['last_success_utc']
    last_success = get_current_source_success(connection)
    last_seen = connection.execute('SELECT MAX(last_seen_utc) FROM events').fetchone()[0]
    for previous in (last_success, last_seen):
        if previous is not None and observed < previous:
            raise OutdatedSnapshot('The public feed is older than the saved UniClubs catalog.')
    _check_identities(document['clubs'], clubs, 'club')
    _check_identities(document['events'], events, 'event')
    for event in document['events']:
        previous = events.get(event['id'])
        if previous is not None and previous['first_seen_utc'] != event['first_seen_utc']:
            raise ValueError('The public feed changed an event first-observation time.')
    return last_success


def _same_snapshot(document, clubs, events):
    """Compare public values, allowing previously retained absent rows already marked missing."""
    for club in document['clubs']:
        if clubs.get(club['id']) != club:
            return False
    incoming_ids = set()
    for event in document['events']:
        incoming_ids.add(event['id'])
        if events.get(event['id']) != event:
            return False
    return all(row['source_missing'] for local_id, row in events.items()
               if local_id not in incoming_ids)


def _write_snapshot(connection, document, clubs, events):
    """Upsert explicit public columns without deleting rows or rewriting private columns."""
    # Course: A07 – INSERT and UPDATE preserve primary keys and existing foreign-key references.
    for club in document['clubs']:
        if club['id'] in clubs:
            connection.execute('UPDATE clubs SET name=?, source_url=? WHERE id=?',
                               (club['name'], club['source_url'], club['id']))
        else:
            connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
                VALUES (?, ?, ?, ?)''', tuple(club[field] for field in uniclubs_export.CLUB_FIELDS))
    incoming_ids = set()
    for event in document['events']:
        incoming_ids.add(event['id'])
        if event['id'] in events:
            values = tuple(event[field] for field in EVENT_UPDATE_FIELDS) + (event['id'],)
            connection.execute(UPDATE_EVENT_SQL, values)
        else:
            values = tuple(event[field] for field in uniclubs_export.EVENT_FIELDS)
            connection.execute(INSERT_EVENT_SQL, values)
    for local_id in events:
        if local_id not in incoming_ids:
            connection.execute('UPDATE events SET source_missing=1 WHERE id=?', (local_id,))


def apply_public_snapshot(connection, payload):
    """Apply a newer public snapshot atomically while preserving user tables and identities.

    :param connection: initialized, idle independent UniClubs catalog connection
    :param payload: decoded versioned public snapshot
    :return: True for a newer applied observation; False for the identical saved observation
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before applying the public feed.')
    document = uniclubs_export.validate_export(payload)
    with connection:
        connection.execute('BEGIN IMMEDIATE')
        clubs, events = _current_catalog(connection)
        previous = _check_snapshot(connection, document, clubs, events)
        if previous == document['_meta']['last_success_utc']:
            if not _same_snapshot(document, clubs, events):
                raise ValueError('The public feed conflicts with the saved observation time.')
            return False
        _write_snapshot(connection, document, clubs, events)
        connection.execute(uniclubs_database.INSERT_LOG_SQL,
                           (document['_meta']['last_success_utc'], 'success',
                            len(document['events']), 'Applied public UniClubs snapshot.'))
    return True


def _checked_at(now):
    """Return the explicit aware check time, separately from the publisher's observation."""
    if now is None:
        return datetime.now(timezone.utc)
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be a timezone-aware datetime.')
    return now.astimezone(timezone.utc)


def _status(connection, checked, ok, changed, message):
    """Return safe UI metadata without raw transport details or full source objects."""
    try:
        source_success = get_current_source_success(connection)
    except sqlite3.Error:
        source_success = None
    return {'ok': ok, 'changed': changed, 'source_success_utc': source_success,
            'checked_at_utc': checked.isoformat(timespec='microseconds').replace('+00:00', 'Z'),
            'message': message}


def fetch_and_apply(connection, now=None):
    """Refresh once while retaining the last saved catalog on network or validation failure.

    :param connection: initialized independent UniClubs catalog connection
    :param now: optional aware local-check clock
    :return: safe ok/changed/source-success/check-time/message status dictionary
    """
    checked = _checked_at(now)
    if connection.in_transaction:
        return _status(connection, checked, False, False,
                       'Finish the current transaction before refreshing UniClubs.')
    try:
        payload = importers.fetch_public_uniclubs_feed()
        changed = apply_public_snapshot(connection, payload)
    except (ValueError, sqlite3.Error, OSError) as error:
        message = 'Could not refresh UniClubs; keeping the last saved catalog.'
        if isinstance(error, OutdatedSnapshot):
            message = 'The feed is older than the saved UniClubs catalog; keeping newer local data.'
        try:
            uniclubs_database.record_import(connection, 'error', message=message, now=checked)
        except sqlite3.Error:
            pass  # The saved catalog is still retained if diagnostic storage is unavailable.
        return _status(connection, checked, False, False, message)
    message = ('UniClubs catalog updated.' if changed else
               'The saved UniClubs catalog matches the downloaded feed.')
    return _status(connection, checked, True, changed, message)
